CREATE OR REPLACE PROCEDURE
  `wfproc_import`(
)
BEGIN
  /*
   {"diagramJson": "{\"title\":\"Film scouting \\u00b7 find_landscapes (MCP tool)\",\"description\":\"Stage 1: rank scouting areas by landscape type and typical weather for the shoot season.\",\"nodes\":[{\"id\":\"s1\",\"data\":{\"id\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_scoring\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"film_scout_scoring\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_scoring\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":432,\"y\":0}},{\"id\":\"n2\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"state IN UNNEST(SPLIT(UPPER(REPLACE(@region, ' ', '')), ',')) AND map_cells >= 10\",\"description\":\"Filter expression\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":608,\"y\":0}},{\"id\":\"n3\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, CASE LOWER(TRIM(@when)) WHEN 'fall' THEN [9, 10, 11] WHEN 'autumn' THEN [9, 10, 11] WHEN 'spring' THEN [3, 4, 5] WHEN 'summer' THEN [6, 7, 8] WHEN 'winter' THEN [12, 1, 2] ELSE [COALESCE(SAFE_CAST(@when AS INT64), CASE SUBSTR(LOWER(TRIM(@when)), 1, 3) WHEN 'jan' THEN 1 WHEN 'feb' THEN 2 WHEN 'mar' THEN 3 WHEN 'apr' THEN 4 WHEN 'may' THEN 5 WHEN 'jun' THEN 6 WHEN 'jul' THEN 7 WHEN 'aug' THEN 8 WHEN 'sep' THEN 9 WHEN 'oct' THEN 10 WHEN 'nov' THEN 11 WHEN 'dec' THEN 12 END, 10)] END AS shoot_months\",\"description\":\"SELECT statement\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":896,\"y\":0}},{\"id\":\"n4\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, (IF(1 IN UNNEST(shoot_months), jan_high_f, 0) + IF(2 IN UNNEST(shoot_months), feb_high_f, 0) + IF(3 IN UNNEST(shoot_months), mar_high_f, 0) + IF(4 IN UNNEST(shoot_months), apr_high_f, 0) + IF(5 IN UNNEST(shoot_months), may_high_f, 0) + IF(6 IN UNNEST(shoot_months), jun_high_f, 0) + IF(7 IN UNNEST(shoot_months), jul_high_f, 0) + IF(8 IN UNNEST(shoot_months), aug_high_f, 0) + IF(9 IN UNNEST(shoot_months), sep_high_f, 0) + IF(10 IN UNNEST(shoot_months), oct_high_f, 0) + IF(11 IN UNNEST(shoot_months), nov_high_f, 0) + IF(12 IN UNNEST(shoot_months), dec_high_f, 0)) / ARRAY_LENGTH(shoot_months) AS season_high_f, (IF(1 IN UNNEST(shoot_months), jan_low_f, 0) + IF(2 IN UNNEST(shoot_months), feb_low_f, 0) + IF(3 IN UNNEST(shoot_months), mar_low_f, 0) + IF(4 IN UNNEST(shoot_months), apr_low_f, 0) + IF(5 IN UNNEST(shoot_months), may_low_f, 0) + IF(6 IN UNNEST(shoot_months), jun_low_f, 0) + IF(7 IN UNNEST(shoot_months), jul_low_f, 0) + IF(8 IN UNNEST(shoot_months), aug_low_f, 0) + IF(9 IN UNNEST(shoot_months), sep_low_f, 0) + IF(10 IN UNNEST(shoot_months), oct_low_f, 0) + IF(11 IN UNNEST(shoot_months), nov_low_f, 0) + IF(12 IN UNNEST(shoot_months), dec_low_f, 0)) / ARRAY_LENGTH(shoot_months) AS season_low_f, (IF(1 IN UNNEST(shoot_months), jan_precip_in, 0) + IF(2 IN UNNEST(shoot_months), feb_precip_in, 0) + IF(3 IN UNNEST(shoot_months), mar_precip_in, 0) + IF(4 IN UNNEST(shoot_months), apr_precip_in, 0) + IF(5 IN UNNEST(shoot_months), may_precip_in, 0) + IF(6 IN UNNEST(shoot_months), jun_precip_in, 0) + IF(7 IN UNNEST(shoot_months), jul_precip_in, 0) + IF(8 IN UNNEST(shoot_months), aug_precip_in, 0) + IF(9 IN UNNEST(shoot_months), sep_precip_in, 0) + IF(10 IN UNNEST(shoot_months), oct_precip_in, 0) + IF(11 IN UNNEST(shoot_months), nov_precip_in, 0) + IF(12 IN UNNEST(shoot_months), dec_precip_in, 0)) / ARRAY_LENGTH(shoot_months) AS season_precip_in, (IF(1 IN UNNEST(shoot_months), jan_sun_mj, 0) + IF(2 IN UNNEST(shoot_months), feb_sun_mj, 0) + IF(3 IN UNNEST(shoot_months), mar_sun_mj, 0) + IF(4 IN UNNEST(shoot_months), apr_sun_mj, 0) + IF(5 IN UNNEST(shoot_months), may_sun_mj, 0) + IF(6 IN UNNEST(shoot_months), jun_sun_mj, 0) + IF(7 IN UNNEST(shoot_months), jul_sun_mj, 0) + IF(8 IN UNNEST(shoot_months), aug_sun_mj, 0) + IF(9 IN UNNEST(shoot_months), sep_sun_mj, 0) + IF(10 IN UNNEST(shoot_months), oct_sun_mj, 0) + IF(11 IN UNNEST(shoot_months), nov_sun_mj, 0) + IF(12 IN UNNEST(shoot_months), dec_sun_mj, 0)) / ARRAY_LENGTH(shoot_months) AS season_sun_mj\",\"description\":\"SELECT statement\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1072,\"y\":0}},{\"id\":\"n5\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, (SELECT AVG(CASE t WHEN 'mountains' THEN match_mountains WHEN 'mountain' THEN match_mountains WHEN 'forest' THEN match_forest WHEN 'forests' THEN match_forest WHEN 'desert' THEN match_desert WHEN 'canyon' THEN match_canyon WHEN 'canyons' THEN match_canyon WHEN 'plains' THEN match_plains WHEN 'alpine' THEN match_alpine WHEN 'wetland' THEN match_wetland WHEN 'wetlands' THEN match_wetland END) FROM UNNEST(SPLIT(REPLACE(REPLACE(REPLACE(LOWER(@landscape), '+', ','), '&', ','), ' ', ''), ',')) AS t) AS landscape_match, CASE WHEN season_high_f BETWEEN 54 AND 82 THEN 1 WHEN season_high_f < 54 THEN LEAST(1, GREATEST(0, (season_high_f - 32) / 22)) ELSE LEAST(1, GREATEST(0, (100 - season_high_f) / 18)) END AS temp_score, LEAST(1, GREATEST(0, 1 - season_precip_in / 5.9)) AS dry_score, PERCENT_RANK() OVER (ORDER BY season_sun_mj) AS sun_score, LEAST(1, GREATEST(0, season_precip_in / 8)) AS wet_score, LEAST(1, GREATEST(0, (75 - season_high_f) / 25)) AS cool_score, LEAST(1, GREATEST(0, (45 - season_high_f) / 20)) AS cold_score, LEAST(1, GREATEST(0, (season_high_f - 80) / 20)) AS heat_score, LEAST(1, GREATEST(0, season_precip_in / 4)) AS snow_wet_score\",\"description\":\"SELECT statement\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1360,\"y\":0}},{\"id\":\"n6\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"weather_score\",\"description\":\"Name for new column\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"CASE LOWER(TRIM(@weather)) WHEN 'rainy' THEN wet_score * 0.5 + (1 - sun_score) * 0.3 + cool_score * 0.2 WHEN 'foggy' THEN wet_score * 0.5 + (1 - sun_score) * 0.3 + cool_score * 0.2 WHEN 'gloomy' THEN wet_score * 0.5 + (1 - sun_score) * 0.3 + cool_score * 0.2 WHEN 'sunny' THEN sun_score * 0.5 + dry_score * 0.5 WHEN 'dry' THEN sun_score * 0.5 + dry_score * 0.5 WHEN 'snowy' THEN cold_score * 0.6 + snow_wet_score * 0.4 WHEN 'cold' THEN cold_score * 0.7 + cool_score * 0.3 WHEN 'hot' THEN heat_score * 0.7 + dry_score * 0.3 ELSE temp_score * 0.4 + dry_score * 0.35 + sun_score * 0.25 END\",\"description\":\"Expression\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1648,\"y\":0}},{\"id\":\"n7\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"score\",\"description\":\"Name for new column\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"landscape_match * (1 - LEAST(1, GREATEST(0, @w_weather))) + weather_score * LEAST(1, GREATEST(0, @w_weather))\",\"description\":\"Expression\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1824,\"y\":0}},{\"id\":\"n8\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"landscape_match >= @min_match\",\"description\":\"Filter expression\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2112,\"y\":0}},{\"id\":\"n9\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"rank\",\"description\":\"Name for new column\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"ROW_NUMBER() OVER (ORDER BY score DESC)\",\"description\":\"Expression\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2288,\"y\":0}},{\"id\":\"n10\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"rank <= @top_n\",\"description\":\"Filter expression\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2464,\"y\":0}},{\"id\":\"n11\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"rank, area_id, area_name, state, ROUND(score, 2) AS score, CASE WHEN rank <= 5 THEN '1 \\u00b7 Top 5' WHEN PERCENT_RANK() OVER (ORDER BY score) >= 0.75 THEN '2 \\u00b7 Top 25%' WHEN PERCENT_RANK() OVER (ORDER BY score) >= 0.5 THEN '3 \\u00b7 Upper middle' WHEN PERCENT_RANK() OVER (ORDER BY score) >= 0.25 THEN '4 \\u00b7 Lower middle' ELSE '5 \\u00b7 Bottom 25%' END AS score_tier, CAST(ROUND(IFNULL(score, 0) * 100) AS INT64) AS score_pct, ROUND(landscape_match, 2) AS landscape_match, ROUND(weather_score, 2) AS weather_score, LOWER(TRIM(@when)) AS shoot_when, LOWER(TRIM(@weather)) AS weather_mood, ROUND(season_high_f) AS avg_high_f, ROUND(season_low_f) AS avg_low_f, ROUND(season_precip_in, 1) AS monthly_precip_in, ROUND(sun_score, 2) AS sun_rank, CASE GREATEST(pct_forest, pct_shrub, pct_grass, pct_barren, pct_crop, pct_developed) WHEN pct_forest THEN 'forest' WHEN pct_shrub THEN 'shrubland' WHEN pct_grass THEN 'grassland' WHEN pct_barren THEN 'barren rock and sand' WHEN pct_crop THEN 'farmland' ELSE 'developed' END AS dominant_landcover, elevation_ft, relief_ft, lat, lon\",\"description\":\"SELECT statement\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2752,\"y\":0}},{\"id\":\"n12\",\"data\":{\"name\":\"native.mcptooloutput\",\"type\":\"generic\",\"label\":\"MCP Tool Output\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"mode\",\"type\":\"Selection\",\"title\":\"Output type\",\"value\":\"sync\",\"description\":\"Output type\"},{\"name\":\"persistTable\",\"type\":\"Boolean\",\"title\":\"Persist table\",\"value\":true,\"description\":\"Save results to a table for later use (slightly slower but reusable)\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2928,\"y\":0}},{\"id\":\"note_overview\",\"data\":{\"name\":\"Note\",\"color\":\"#E5E5E5\",\"genAi\":false,\"label\":\"\",\"width\":360,\"height\":820,\"inputs\":[],\"markdown\":\"---\\nlabel: find_landscapes (MCP tool)\\n---\\n## find_landscapes\\n**Stage 1 tool the agent calls: the look.**\\n\\nInputs: `region`, `landscape` (type or list, e.g. `forest,mountains`), `when` (season or month), `weather` (mood: comfortable, rainy, sunny, snowy, cold, hot), `w_weather`, `min_match`, `top_n`.\\n\\nReturns **every area** whose landscape match is at least `min_match`, ranked by score = landscape match + weather fit.\\n\\nReads `film_scout_scoring` (landscape-type scores are precomputed there by workflow 2). Published as an MCP tool, so edits take effect after **Publish**.\",\"position\":{\"x\":0,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":0,\"y\":-300}},{\"id\":\"note_1\",\"data\":{\"name\":\"Note\",\"color\":\"#F6CF71\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 1. Region\\n---\\n**Where** keeps areas in the requested states with at least 10 res-6 cells (skips slivers at the edges).\",\"position\":{\"x\":408,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":408,\"y\":-300}},{\"id\":\"note_2\",\"data\":{\"name\":\"Note\",\"color\":\"#9EB9F3\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 2. Season climate\\n---\\n- **Select** turns `when` into a list of months (fall = Sep-Nov).\\n- **Select** averages highs, lows, precipitation and sunshine over those months.\",\"position\":{\"x\":872,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":872,\"y\":-300}},{\"id\":\"note_3\",\"data\":{\"name\":\"Note\",\"color\":\"#87C55F\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 3. Landscape match + weather\\n---\\n**Select** picks the precomputed `match_` score for the requested type(s) (a list is averaged) and computes the weather ingredients (warmth, dryness, sunshine, wetness, cold, heat).\",\"position\":{\"x\":1336,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1336,\"y\":-300}},{\"id\":\"note_4\",\"data\":{\"name\":\"Note\",\"color\":\"#FE88B1\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 4. Weather mood and score\\n---\\n- **Create Column**: weather fit for the requested mood (comfortable = best crew conditions; rainy, sunny, snowy, cold, hot = on-screen look).\\n- **Create Column**: score = (1 - `w_weather`) x landscape match + `w_weather` x weather.\",\"position\":{\"x\":1624,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1624,\"y\":-300}},{\"id\":\"note_5\",\"data\":{\"name\":\"Note\",\"color\":\"#C9DB74\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 5. Keep matches and rank\\n---\\n- **Where** keeps areas with landscape match >= `min_match`.\\n- **Create Column** ranks by score.\\n- **Where** caps the list at `top_n`.\",\"position\":{\"x\":2088,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2088,\"y\":-300}},{\"id\":\"note_6\",\"data\":{\"name\":\"Note\",\"color\":\"#8BE0A4\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 6. Output\\n---\\n- **Select** tidies the output and adds `score_tier` (Top 5 ... Bottom 25%) for map styling.\\n- **MCP Tool Output** (sync, saved table) returns rows to the agent and a table it can add to the map.\",\"position\":{\"x\":2728,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2728,\"y\":-300}}],\"edges\":[{\"id\":\"e1\",\"source\":\"s1\",\"target\":\"n2\",\"sourceHandle\":\"out\",\"targetHandle\":\"source\"},{\"id\":\"e2\",\"source\":\"n2\",\"target\":\"n3\",\"sourceHandle\":\"match\",\"targetHandle\":\"table\"},{\"id\":\"e3\",\"source\":\"n3\",\"target\":\"n4\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"e4\",\"source\":\"n4\",\"target\":\"n5\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"e5\",\"source\":\"n5\",\"target\":\"n6\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e6\",\"source\":\"n6\",\"target\":\"n7\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e7\",\"source\":\"n7\",\"target\":\"n8\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e8\",\"source\":\"n8\",\"target\":\"n9\",\"sourceHandle\":\"match\",\"targetHandle\":\"source\"},{\"id\":\"e9\",\"source\":\"n9\",\"target\":\"n10\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e10\",\"source\":\"n10\",\"target\":\"n11\",\"sourceHandle\":\"match\",\"targetHandle\":\"table\"},{\"id\":\"e11\",\"source\":\"n11\",\"target\":\"n12\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"}],\"variables\":[{\"name\":\"region\",\"type\":\"String\",\"order\":1,\"value\":\"WA,OR,ID\",\"scopes\":[\"mcptool\"],\"helperText\":\"Comma-separated state codes\",\"displayName\":\"Region (state codes)\"},{\"name\":\"landscape\",\"type\":\"String\",\"order\":2,\"value\":\"mountains\",\"scopes\":[\"mcptool\"],\"helperText\":\"mountains, forest, desert, canyon, plains, alpine or wetland; comma-separate to combine\",\"displayName\":\"Landscape\"},{\"name\":\"when\",\"type\":\"String\",\"order\":3,\"value\":\"fall\",\"scopes\":[\"mcptool\"],\"helperText\":\"fall, spring, summer, winter, or a month (oct or 10)\",\"displayName\":\"When\"},{\"name\":\"weather\",\"type\":\"String\",\"order\":4,\"value\":\"comfortable\",\"scopes\":[\"mcptool\"],\"helperText\":\"comfortable, rainy, sunny, snowy, cold or hot\",\"displayName\":\"Weather mood\"},{\"name\":\"w_weather\",\"type\":\"Number\",\"order\":5,\"value\":\"0.3\",\"scopes\":[\"mcptool\"],\"helperText\":\"0-1 share of the score from weather\",\"displayName\":\"Weight: weather\"},{\"name\":\"min_match\",\"type\":\"Number\",\"order\":6,\"value\":\"0.6\",\"scopes\":[\"mcptool\"],\"helperText\":\"0-1; areas below this are not a match\",\"displayName\":\"Minimum landscape match\"},{\"name\":\"top_n\",\"type\":\"Number\",\"order\":7,\"value\":\"300\",\"scopes\":[\"mcptool\"],\"helperText\":\"Return all matching areas, up to this many\",\"displayName\":\"Max results\"}],\"procedure\":{},\"schedule\":{},\"viewport\":{\"x\":0,\"y\":0,\"zoom\":0.7},\"schemaVersion\":\"1.0.0\",\"connectionProvider\":\"bigquery\",\"useCache\":false,\"mcpTool\":{\"draft\":{\"name\":\"find_landscapes\",\"inputs\":{\"when\":{\"description\":\"Shoot season or month: 'fall' (Sep-Nov), 'spring' (Mar-May), 'summer' (Jun-Aug), 'winter' (Dec-Feb), or a month such as 'oct' or '10'.\"},\"top_n\":{\"description\":\"Maximum number of matching areas to return (default 300). Results are all matches, ranked by score.\"},\"region\":{\"description\":\"Comma-separated US state codes. Common regions: Pacific Northwest = 'WA,OR,ID'; California = 'CA'; Southwest = 'AZ,NM,NV,UT'; Four Corners = 'AZ,NM,UT,CO'; Rockies = 'MT,WY,CO,ID,UT'; whole West = 'WA,OR,ID,MT,WY,CA,NV,UT,CO,AZ,NM'.\"},\"weather\":{\"description\":\"Weather mood to reward: 'comfortable' (default: mild highs 54-82F, dry, sunny - best for the crew), 'rainy' (also 'foggy', 'gloomy': wet, overcast, cool), 'sunny' (also 'dry'), 'snowy' (cold and wet), 'cold', or 'hot'. Choose from the creative brief, not production comfort.\"},\"landscape\":{\"description\":\"One of mountains, forest, desert, canyon, plains, alpine, wetland, or a comma-separated combination such as 'forest,mountains' (the match is the average of the listed types).\"},\"min_match\":{\"description\":\"0-1 (default 0.6). Minimum landscape match for an area to count. Use 0.75 for a strict look, 0.5 to include near-misses.\"},\"w_weather\":{\"description\":\"0-1 (default 0.3). Share of the score that comes from weather; the rest is landscape match. 0 = look only, 0.5 = mood matters as much as the land.\"}},\"output\":{\"description\":\"One row per area; sort by rank. score_tier (1 \\u00b7 Top 5 ... 5 \\u00b7 Bottom 25%; color map layers by this) and score_pct (0-100). area_id (pass to score_locations), area_name (county, state), state, score (0-1: (1 - w_weather) x landscape_match + w_weather x weather_score), landscape_match, weather_score (0-1 fit to the requested weather mood), shoot_when, weather_mood, avg_high_f, avg_low_f, monthly_precip_in (average per month in the season), sun_rank (0-1 vs the other areas searched), dominant_landcover, elevation_ft, relief_ft (highest minus lowest point in the area), lat, lon. area_id is an H3 resolution-4 cell index: map results with geoColumn h3:area_id.\"},\"description\":\"Stage 1 of film location scouting in the 11 western US states. Ranks scouting AREAS (about 40 km across) by how well their landscape matches the requested type and how good the typical weather is for the requested weather mood in the shoot season. Use FIRST. Returns EVERY area whose landscape_match is at least min_match (not just one per region), ranked by score: map all of them, and summarize only the top few in chat. Then call score_locations with the same region, landscape, when, weather, w_weather and min_match (area_ids empty) to score incentives, airport access, hotels and healthcare for exactly this set of areas. Weather is long-term climate averages (WorldClim), not a forecast; land cover is USDA/NLCD. Creative-brief presets (set these inputs): horror / thriller = landscape 'forest,wetland', weather 'rainy', w_weather 0.5; gloomy Pacific Northwest = 'forest', 'rainy', 0.5; epic vista = 'mountains,alpine', 'sunny', 0.3; classic western = 'desert,canyon', 'sunny', 0.3; winter drama = 'mountains,forest', 'snowy', 0.5; heartland / farm = 'plains', 'comfortable', 0.3. If the brief names no weather, use 'comfortable' (best shooting conditions).\"},\"name\":\"find_landscapes\",\"description\":\"Stage 1 of film location scouting in the 11 western US states. Ranks scouting AREAS (about 40 km across) by how well their landscape matches the requested type and how good the typical weather is for the requested weather mood in the shoot season. Use FIRST. Returns EVERY area whose landscape_match is at least min_match (not just one per region), ranked by score: map all of them, and summarize only the top few in chat. Then call score_locations with the same region, landscape, when, weather, w_weather and min_match (area_ids empty) to score incentives, airport access, hotels and healthcare for exactly this set of areas. Weather is long-term climate averages (WorldClim), not a forecast; land cover is USDA/NLCD. Creative-brief presets (set these inputs): horror / thriller = landscape 'forest,wetland', weather 'rainy', w_weather 0.5; gloomy Pacific Northwest = 'forest', 'rainy', 0.5; epic vista = 'mountains,alpine', 'sunny', 0.3; classic western = 'desert,canyon', 'sunny', 0.3; winter drama = 'mountains,forest', 'snowy', 0.5; heartland / farm = 'plains', 'comfortable', 0.3. If the brief names no weather, use 'comfortable' (best shooting conditions).\",\"enabled\":false},\"viewerMode\":{},\"executionSettings\":{\"cacheModes\":{\"api\":false,\"mcp\":false,\"editor\":false,\"viewer\":false}}}"}
  */
END;
